from textlesson import build
S=dict(cls=6,subj="science",subj_file="science")
def Q(*a): return list(a)
build(dict(S,ch="mindful-eating-a-path-to-a-healthy-body",topic="balanced-diet",name_en="A balanced diet",name_ta="சமச்சீர் உணவு",
 objectives=["Say what a balanced diet is","Link foods to the nutrient they give"],
 story=("Ravi's lunch box","Ravi's lunch box had only fried chips every day. By evening he felt tired and weak.\nHis teacher said, \"Your body needs many kinds of food, not only one.\"\nNext day his mother packed chapati, dal, a vegetable and a banana."),
 explain=["A balanced diet has all the nutrients our body needs in the right amounts: carbohydrates, proteins, fats, vitamins, minerals, fibre and water.","Cereals like rice and wheat give energy. Pulses, milk, eggs and fish help the body grow and repair. Fruits and vegetables give vitamins, minerals and fibre.","Eating too little causes weakness, and eating too much junk food or sugar can make us unwell. We should eat a variety of foods, drink enough water and eat on time."],
 terms=["balanced diet","nutrients","fibre","junk food"],
 narr=[("A balanced diet has all the nutrients in the right amounts.","all nutrients"),("Rice and wheat give energy. Pulses, milk and eggs help us grow.","energy and growth foods"),("Fruits and vegetables give vitamins, minerals and fibre.","fruits and vegetables"),("Eat a variety of food, drink water and avoid too much junk food.","variety, water, less junk")],
 ex=("Ravi eats only chips. Which foods should he add to balance his meal?",[("Chips give mostly fat and salt.","They lack other nutrients."),("He should add cereal for energy, dal or milk for growth, and fruit and vegetables for vitamins.","Each group gives a different nutrient."),("Now his meal has many nutrients, so it is balanced.","Variety is the key.")]),
 tb=("A friend says eating only sweets is fine because they give energy. What will you say?",["Sweets give energy but few other nutrients.","The body needs proteins, vitamins and minerals too."],["Thinking one kind of food is enough."]),
 summary=["A balanced diet has all nutrients in the right amount.","Eat cereals, pulses, fruits, vegetables and drink water.","Too much junk food is not good."],
 q=[("mcq",1,"r1-energy","Which food mainly gives energy?","rice",[("water","Water has no energy."),("salt","Salt is a mineral.")],"Cereals such as rice give energy."),
    ("tf",1,"r1-bal","A balanced diet has all the nutrients we need.",True,"True."),
    ("mcq",2,"r2-grow","Which food helps the body grow and repair?","dal",[("sugar","Sugar mainly gives energy."),("tea","Tea does not help repair the body.")],"Pulses give proteins."),
    ("tf",2,"r2-junk","Eating a lot of junk food is good for health.",False,"False."),
    ("mcq",3,"r3-fibre","Which gives fibre?","vegetables",[("butter","Butter is fat."),("ghee","Ghee is fat.")],"Fruits and vegetables give fibre."),
    ("short",3,"r3-name","Name one food rich in vitamins.",["orange","banana","mango","guava","carrot","papaya","apple","fruit","vegetable","spinach"],"Fruits and vegetables give vitamins."),
    ("mcq",4,"r4-habit","A healthy eating habit is to","eat a variety of foods",[("skip breakfast","Breakfast gives energy."),("eat only fried food","It is not balanced.")],"Variety gives all nutrients."),
    ("tf",4,"r4-water","We should drink enough water every day.",True,"True.")]))
build(dict(S,ch="materials-around-us",topic="properties-of-materials",name_en="Properties of materials",name_ta="பொருட்களின் பண்புகள்",
 objectives=["Name properties used to compare materials","Choose a material for a use"],
 story=("The window and the wall","Asha asked, \"Why is a window made of glass but a wall made of bricks?\"\nHer teacher said, \"Glass lets light pass, so we can see through it. Bricks are hard and strong and do not let light pass.\"\n\"So each material is used for a reason,\" said Asha."),
 explain=["Materials are compared by their properties. Appearance can be shiny or dull. Hardness tells how easily a material is scratched: iron is hard, chalk is soft.","Transparent materials such as clear glass let light pass so we can see clearly. Translucent materials such as thin paper let some light pass. Opaque materials such as wood and metal do not let light pass.","Some materials dissolve in water, such as salt and sugar, and some do not, such as sand and oil. Some float and some sink. We use the right material for each job."],
 terms=["transparent","translucent","opaque","soluble","property"],
 narr=[("We compare materials by their properties, like shiny or dull, hard or soft.","properties"),("Transparent things let light pass. Translucent things let some light pass. Opaque things let none pass.","transparent, translucent, opaque"),("Salt and sugar dissolve in water. Sand and oil do not.","dissolve or not"),("We choose materials for a job by their properties.","right material, right job")],
 ex=("Why are windows made of glass and not of wood?",[("We need light to come in and to see outside.","So the material must let light pass."),("Clear glass is transparent but wood is opaque.","Wood blocks light."),("So glass is the right material for a window.","Use depends on property.")]),
 tb=("A friend says all see-through things are glass. How will you explain?",["Clear plastic is also transparent.","So a material can be transparent without being glass."],["Thinking only glass lets light pass."]),
 summary=["Properties help us compare materials.","Transparent, translucent and opaque describe how light passes.","We choose materials by their properties."],
 q=[("mcq",1,"r1-trans","Clear glass is","transparent",[("opaque","Opaque blocks light."),("translucent","Translucent lets only some light through.")],"We can see clearly through it."),
    ("tf",1,"r1-wood","Wood is opaque.",True,"True."),
    ("mcq",2,"r2-sol","Which dissolves in water?","sugar",[("sand","Sand does not dissolve."),("oil","Oil does not mix with water.")],"Sugar is soluble."),
    ("tf",2,"r2-chalk","Chalk is harder than iron.",False,"False. Iron is harder."),
    ("mcq",3,"r3-trl","Thin paper that lets some light pass is","translucent",[("transparent","Transparent lets all light pass."),("opaque","Opaque lets none pass.")],"It lets some light through."),
    ("short",3,"r3-ex","Name one opaque material.",["wood","metal","iron","stone","brick","cardboard","steel","wall"],"Wood and metals are opaque."),
    ("mcq",4,"r4-use","Cooking vessels are made of metal because metals","let heat pass easily",[("float on water","That is not why."),("are transparent","They are not transparent.")],"Metals are good conductors of heat."),
    ("tf",4,"r4-choice","We choose a material for its properties.",True,"True.")]))
build(dict(S,ch="temperature-and-its-measurement",topic="hot-cold-and-heat-flow",name_en="Hot, cold and heat flow",name_ta="சூடு, குளிர், வெப்பப் பரவல்",
 objectives=["Say that heat flows from hot to cold","Name good and poor conductors of heat"],
 story=("The hot spoon","Kavya left a steel spoon in a hot cup of tea. After a minute the handle was hot too.\n\"How did the heat reach my hand?\" she asked.\n\"Heat flows along the metal,\" said her aunt. \"A wooden spoon would stay cool.\""),
 explain=["Heat is a form of energy. It always flows from a hotter object to a colder object until both are at the same temperature.","Materials that let heat pass easily are good conductors, such as metals. Materials that do not, such as wood, plastic and cloth, are poor conductors or insulators.","That is why pots are made of metal with plastic or wooden handles. Woollen clothes keep us warm because they hold in the heat of our body."],
 terms=["heat","conductor","insulator","temperature"],
 narr=[("Heat always flows from a hot object to a cold object.","hot to cold"),("Metals let heat pass easily. They are good conductors.","metals conduct"),("Wood, plastic and cloth do not let heat pass easily. They are insulators.","insulators"),("Pots have metal bodies and plastic handles for this reason.","metal pot, plastic handle")],
 ex=("Why does a steel spoon in hot tea become hot but a wooden spoon does not?",[("Heat flows from the hot tea into the spoon.","Hot to cold."),("Steel is a good conductor, so heat travels quickly along it.","Metals conduct well."),("Wood is an insulator, so heat does not travel easily.","So the wooden spoon stays cool.")]),
 tb=("A friend says a woollen sweater makes you warm because it produces heat. How will you explain?",["A sweater does not make heat.","It is an insulator that keeps the heat of your body from escaping."],["Thinking clothes produce heat."]),
 summary=["Heat flows from hot to cold.","Metals are good conductors; wood and plastic are insulators.","Insulators keep things warm or cool."],
 q=[("mcq",1,"r1-flow","Heat flows from","a hot object to a cold object",[("a cold object to a hot object","Heat does not flow that way by itself."),("nowhere","Heat does flow.")],"Until both are at the same temperature."),
    ("tf",1,"r1-metal","Metals are good conductors of heat.",True,"True."),
    ("mcq",2,"r2-ins","Which is an insulator?","wood",[("copper","Copper is a conductor."),("iron","Iron is a conductor.")],"Wood does not let heat pass easily."),
    ("tf",2,"r2-wool","Woollen clothes help to keep body heat in.",True,"True."),
    ("mcq",3,"r3-handle","Pan handles are made of plastic because plastic is","a poor conductor",[("a good conductor","Then the handle would become hot."),("shiny","That is not the reason.")],"It does not let heat pass."),
    ("short",3,"r3-name","Name one good conductor of heat.",["iron","copper","steel","aluminium","silver","metal","brass"],"Metals conduct heat."),
    ("mcq",4,"r4-ice","If you hold an ice cube, your hand feels cold because heat flows","from your hand to the ice",[("from the ice to your hand","The hand is warmer."),("not at all","Heat flows from hot to cold.")],"Your hand loses heat."),
    ("tf",4,"r4-temp","Temperature tells how hot or cold something is.",True,"True.")]))
build(dict(S,ch="a-journey-through-states-of-water",topic="the-water-cycle",name_en="The water cycle",name_ta="நீர் சுழற்சி",
 objectives=["Describe evaporation, condensation and rain","Draw the water cycle in order"],
 story=("The wet clothes","Mina hung wet clothes in the sun. After some time they were dry.\n\"Where did the water go?\" she asked.\nHer grandmother said, \"It went into the air as vapour. One day it will come back as rain.\""),
 explain=["Water on the ground, in rivers, lakes and seas is heated by the Sun and changes into water vapour. This is evaporation.","Water vapour rises, cools in the sky and changes into tiny drops that form clouds. This is condensation.","When the drops in clouds become heavy, they fall as rain, snow or hail. This is precipitation. The water flows into rivers and the sea, and the cycle goes on and on."],
 terms=["evaporation","condensation","water vapour","water cycle","precipitation"],
 narr=[("The Sun heats water and it rises as water vapour. This is evaporation.","evaporation"),("High up, the vapour cools and turns into tiny drops that make clouds. This is condensation.","condensation"),("When the drops become heavy they fall as rain. Rivers carry the water to the sea.","rain"),("Then the cycle starts again. This is the water cycle.","cycle repeats")],
 ex=("Put these in order: rain falls, water evaporates, clouds form.",[("First the Sun heats water and it evaporates.","Evaporation comes first."),("Then the vapour cools and forms clouds.","This is condensation."),("Finally the clouds give rain. So: evaporate, clouds form, rain falls.","The cycle then repeats.")]),
 tb=("A friend asks where rain water comes from. Explain in two lines.",["Water from seas and rivers evaporates and rises.","It cools into clouds and falls back as rain."],["Thinking rain is made in the clouds from nothing."]),
 summary=["Evaporation turns water into vapour.","Condensation turns vapour into drops and clouds.","Rain brings water back, and the cycle repeats."],
 q=[("mcq",1,"r1-evap","Water changing into vapour is","evaporation",[("condensation","That is vapour changing to water."),("freezing","That is water changing to ice.")],"Heat makes water evaporate."),
    ("tf",1,"r1-sun","The Sun helps water to evaporate.",True,"True."),
    ("mcq",2,"r2-cond","Clouds are formed by","condensation",[("evaporation","That makes vapour."),("melting","That is ice to water.")],"Vapour cools and condenses."),
    ("tf",2,"r2-vapour","Water vapour can be seen easily as a blue gas.",False,"False. It is invisible."),
    ("mcq",3,"r3-rain","Rain falls when","drops in clouds become heavy",[("the clouds get lighter","They fall when heavy."),("the Sun sets","That does not cause rain.")],"The heavy drops fall."),
    ("short",3,"r3-step","What do we call water falling from clouds?",["rain","precipitation"],"Rain, snow and hail are precipitation."),
    ("mcq",4,"r4-dry","Wet clothes dry because the water","evaporates",[("freezes","It does not freeze."),("disappears forever","It goes into the air.")],"It goes into the air as vapour."),
    ("tf",4,"r4-cycle","The water cycle goes on again and again.",True,"True.")]))
